const proList = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/house-cleaning/"]'));
  const uniquePros = [];
  const seen = new Set();
  for (const link of links) {
    const text = link.innerText?.trim();
    const href = link.href;
    if (text && !seen.has(href) && (text.includes("hires") || text.includes("rating") || text.includes("View profile") || text.includes("★") || text.includes("5.0") || text.includes("4."))) {
      seen.add(href);
      uniquePros.push({
        text,
        href
      });
    }
  }
  return uniquePros;
});

console.log("Found pros:", JSON.stringify(proList.slice(0, 10), null, 2));

